. "$PSScriptRoot/../autosprite-rune-seer-headless-2026-10-16/mcp-client.ps1"
if(Test-Path "$PSScriptRoot/generation-request.json"){throw 'Existing submission: inspect receipt; never create a second paid job.'}
$fixUpload=Invoke-AutoSpriteTool -Name upload_character -Arguments @{name='Miko exact original costume - empty hands and bare back';imageUrl=('data:image/png;base64,'+[Convert]::ToBase64String([IO.File]::ReadAllBytes("$PSScriptRoot/input.png")));isHumanoid=$true}
@{id=$fixUpload.character.id;source='input.png';uploadCredits=0}|ConvertTo-Json|Set-Content "$PSScriptRoot/character.json" -Encoding utf8
$fixArgs=@{characterId=$fixUpload.character.id;action='custom';name='Miko Empty Hands Bare Back Walk';loop=$true;frameCount=56;frameSize=256;idempotencyKey=('miko-unarmed-fix-'+[guid]::NewGuid().ToString());prompt='Animate ONLY the exact uploaded headless Miko costume, walking naturally in place in ALL EIGHT directions. Preserve the identical ivory kimono sleeves, crimson hakama skirt, red sleeve trim and sash, small paper charms, sandals, palette, pixel detail and compact proportions. The back consists ONLY of the SAME soft kimono fabric and sash: NO rigid diagonal objects, NO scabbard, NO sword handle, NO sheathed sword, NO bow, NO quiver, NO rod, staff, wand, spear, weapon, equipment or prop attached to the back or belt. BOTH HANDS COMPLETELY EMPTY through EVERY frame in EVERY direction. No weapon at all, including on back and hips. Leave the neck stump exposed and all space above it transparent: NO head, face, hair, hat or helmet. Alternate planted feet, heel contact and toe-off; arms swing OPPOSITE the same-side leg with relaxed elbows. Keep feet grounded and torso stable with modest vertical bob. Seamless continuous full walk cycle, final frame phase flows immediately into first with matching limb phase and cloth motion. No stationary ending, no stop/reset, no camera movement, no traveling, no background, no effects or shadows. Preserve crisp detailed pixel clusters without redesigning the outfit.'}
@{approvedCredits=15;scope='one eight-direction Miko replacement; no paid retry';inputSha256=(Get-FileHash "$PSScriptRoot/input.png" -Algorithm SHA256).Hash}|ConvertTo-Json|Set-Content "$PSScriptRoot/approval.json" -Encoding utf8
$fixArgs|ConvertTo-Json -Depth 10|Set-Content "$PSScriptRoot/generation-request.json" -Encoding utf8
$fixJob=Invoke-AutoSpriteTool -Name generate_isometric_pack -Arguments $fixArgs
$fixJob|ConvertTo-Json -Depth 12|Set-Content "$PSScriptRoot/generation-job.json" -Encoding utf8
$fixJob|ConvertTo-Json -Depth 12
